def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Full divider rows/columns split the grid into panels.
    divrows = [r for r in range(h) if len(set(g[r])) == 1]
    divcols = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1]
    rb = [-1] + divrows + [h]
    cb = [-1] + divcols + [w]
    panels = [(rb[i] + 1, rb[i + 1], cb[j] + 1, cb[j + 1])
              for i in range(len(rb) - 1) for j in range(len(cb) - 1)]

    # The panel containing non-background objects is the pattern to repeat.
    # Background is the most frequent color among non-divider cells.
    divider_cells = {(r, c) for r in divrows for c in range(w)}
    divider_cells |= {(r, c) for c in divcols for r in range(h)}
    from collections import Counter
    counts = Counter(g[r][c] for r in range(h) for c in range(w)
                     if (r, c) not in divider_cells)
    bg = counts.most_common(1)[0][0]

    source = max(panels, key=lambda p: sum(
        g[r][c] != bg for r in range(p[0], p[1]) for c in range(p[2], p[3])
    ))
    r0, r1, c0, c1 = source
    pattern = [row[c0:c1] for row in g[r0:r1]]

    for a, b, x, y in panels:
        if (a, b, x, y) == source:
            continue
        for r in range(a, b):
            for c in range(x, y):
                g[r][c] = pattern[(r - a) % len(pattern)][(c - x) % len(pattern[0])]
    return g
